from src.nodes.base import BaseNode
from src.runtime.assets.realization import get_usd_builder
import json

class Hou_Mcp_Usd_Builder(BaseNode):
    name = "hou_mcp_usd_builder"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("asset_json",     "string", widget_type="text")
        self.add_input("materials_json", "string", widget_type="text", default="")
        self.add_output("usd_asset_json",     "string")
        self.add_output("usd_hierarchy_json", "string")
        self.add_output("usd_metadata_json",  "string")
        self.add_output("build_ok",           "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        asset_json    = inputs.get("asset_json", "") or ""
        materials_json = inputs.get("materials_json", "") or ""

        if not asset_json.strip():
            self.log_error("No asset_json provided.")
            return {"usd_asset_json": "{}", "usd_hierarchy_json": "{}", "usd_metadata_json": "{}", "build_ok": False, "exec_out": True}

        try:
            asset = json.loads(asset_json)
        except Exception as exc:
            self.log_error(f"Failed to parse asset_json: {exc}")
            return {"usd_asset_json": "{}", "usd_hierarchy_json": "{}", "usd_metadata_json": "{}", "build_ok": False, "exec_out": True}

        materials = []
        if materials_json.strip():
            try:
                materials = json.loads(materials_json)
                if isinstance(materials, dict):
                    materials = [materials]
            except Exception:
                pass

        try:
            builder = get_usd_builder()
            result    = builder.build_usd_asset(asset, materials)
            hierarchy = builder.build_usd_hierarchy(asset)
            metadata  = builder.build_usd_metadata(asset)
            self.log_info(f"USD build: '{asset.get('name', '')}' ok={result.ok}")
            return {
                "usd_asset_json":     json.dumps(result.asset.to_dict() if result.asset else {}, sort_keys=True, default=str),
                "usd_hierarchy_json": json.dumps(hierarchy, sort_keys=True, default=str),
                "usd_metadata_json":  json.dumps(metadata, sort_keys=True, default=str),
                "build_ok":           result.ok,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"USD build failed: {exc}")
            return {"usd_asset_json": "{}", "usd_hierarchy_json": "{}", "usd_metadata_json": "{}", "build_ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Usd_Builder
